#!/bin/bash

mkdir -p /var/www/html/storage/framework/{sessions,views,cache}
php /var/www/html/artisan storage:link
php /var/www/html/artisan optimize:clear
php /var/www/html/artisan filament:clear
php -r 'opcache_reset();'
php /var/www/html/artisan config:cache
php /var/www/html/artisan route:cache
php /var/www/html/artisan view:cache
php /var/www/html/artisan event:cache
# Wait until db is online
echo "Wait for DB to be ready"
while ! nc -z database 3306; do
    sleep 0.5
    echo "Wait 0.5 seconds"
done
echo "DB is ready"
sleep 1
php /var/www/html/artisan migrate --force

exec "$@"
#!/bin/bash

echo "Starting the app"
nginx && docker-php-entrypoint php-fpm
server {
    listen 80 default_server;
    server_name _;
    server_tokens off;
    root /var/www/html/public;

    add_header X-Frame-Options "SAMEORIGIN";
    add_header X-XSS-Protection "1; mode=block";
    add_header X-Content-Type-Options "nosniff";
    client_max_body_size 3M;
    client_body_temp_path /tmp;

    index index.html index.htm index.php;

    charset utf-8;

    location / {
        try_files $uri $uri/ /index.php?$query_string;
    }

    location = /favicon.ico { access_log off; log_not_found off; }
    location = /robots.txt  { access_log off; log_not_found off; }

    error_page 404 /index.php;

    location ~ \.php$ {
        fastcgi_split_path_info ^(.+\.php)(/.+)$;
        fastcgi_pass 127.0.0.1:9000;
        fastcgi_index index.php;
        include fastcgi.conf;
    }

    location ~ /\.(?!well-known).* {
        deny all;
    }

    # fix cors for local development with swagger ui
    # http://localhost:3001/v1_openapi.json
    location = /v1_openapi.json {
        add_header Access-Control-Allow-Origin *;
        add_header Access-Control-Allow-Methods "GET, OPTIONS";
        add_header Access-Control-Allow-Headers "DNT,User-Agent,X-Requested-With,If-Modified-Since,Cache-Control,Content-Type,Range";
        add_header Access-Control-Expose-Headers "Content-Length,Content-Range";
    }

    location ~* \.(ico|pdf|flv|jpg|jpeg|png|gif|js|css|swf)$ {
        expires 1h;
        add_header Cache-Control "public, no-transform";
    }

    gzip on;
    gzip_disable "msie6";
    gzip_vary on;
    gzip_proxied any;
    gzip_comp_level 6;
    gzip_buffers 16 8k;
    gzip_http_version 1.1;
    gzip_min_length 256;
    gzip_types
    application/atom+xml
    application/geo+json
    application/javascript
    application/x-javascript
    application/json
    application/ld+json
    application/manifest+json
    application/rdf+xml
    application/rss+xml
    application/xhtml+xml
    application/xml
    font/eot
    font/otf
    font/ttf
    image/svg+xml
    text/css
    text/javascript
    text/plain
    text/xml;
}
